            // Render UI
            draw_screen(&opts);

            refresh();

            // Handle input
            int ch = getch();
            if (ch == 'q') {
                running = 0;
            }

            usleep(opts.delay * 100000); // Convert tenths of seconds to microseconds

            if (opts.max_iterations > 0) {
                iterations++;
                if (iterations >= opts.max_iterations) {
                    running = 0;
                }
            }
        }

        endwin();
    } else {
        // Non-interactive mode for testing
        initscr();
        cbreak();
        noecho();

        if (!opts.no_color) {
            start_color();
            init_default_colors();
        }

        for (int i = 0; i < opts.max_iterations; i++) {
            clear();
            draw_screen(&opts);
            refresh();
            usleep(opts.delay * 100000);
        }

        endwin();
    }

