#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <unistd.h>
#include <pwd.h>
#include <sys/stat.h>
#include "process.h"

Process** get_processes(int *count, const Options *opts) {
    Process **processes = NULL;
    *count = 0;
    int capacity = 100;

    processes = malloc(capacity * sizeof(Process*));

    DIR *proc = opendir("/proc");
    if (!proc) {
        return processes;
    }

    struct dirent *entry;
    while ((entry = readdir(proc)) != NULL) {
        if (!isdigit(entry->d_name[0])) {
            continue;
        }

        pid_t pid = atoi(entry->d_name);

        char path[256];
        snprintf(path, sizeof(path), "/proc/%d/stat", pid);

        FILE *f = fopen(path, "r");
        if (!f) continue;

        Process *p = malloc(sizeof(Process));
        memset(p, 0, sizeof(Process));

        // Parse /proc/[pid]/stat
        int num = fscanf(f, "%d %*s %c %d %d %d %d %*d %*u %*u %*u %*u %*u %lu %lu %lu %lu",
                         &p->pid, &p->state, &p->ppid, &p->pgrp, &p->session,
                         &p->utime, &p->stime, &p->cutime, &p->cstime);
        fclose(f);

        if (num < 9) {
            free(p);
            continue;
        }

        // Read command name
        snprintf(path, sizeof(path), "/proc/%d/comm", pid);
        f = fopen(path, "r");
        if (f) {
            char comm[256];
            if (fgets(comm, sizeof(comm), f)) {
                size_t len = strlen(comm);
                if (len > 0 && comm[len-1] == '\n') {
                    comm[len-1] = '\0';
                }
                p->command = strdup(comm);
            }
            fclose(f);
        }

        // Get UID and username
        struct stat st;
        snprintf(path, sizeof(path), "/proc/%d", pid);
        if (stat(path, &st) == 0) {
            p->uid = st.st_uid;
            struct passwd *pw = getpwuid(st.st_uid);
            if (pw) {
                p->user = strdup(pw->pw_name);
            } else {
                char uidstr[32];
                snprintf(uidstr, sizeof(uidstr), "%d", st.st_uid);
                p->user = strdup(uidstr);
            }
        }

        if (*count >= capacity) {
            capacity *= 2;
            processes = realloc(processes, capacity * sizeof(Process*));
        }

        if (process_passes_filter(p, opts)) {
            processes[*count] = p;
            (*count)++;
        } else {
            free(p->command);
            free(p->user);
            free(p);
        }
    }

    closedir(proc);
    return processes;
}

void free_processes(Process **processes, int count) {
    for (int i = 0; i < count; i++) {
        if (processes[i]) {
            free(processes[i]->command);
            free(processes[i]->user);
            free(processes[i]->cmd_full);
            free(processes[i]);
        }
    }
    free(processes);
}

int process_passes_filter(const Process *p, const Options *opts) {
    if (!p) return 0;

    if (opts->pid_count > 0) {
        int found = 0;
        for (int i = 0; i < opts->pid_count; i++) {
            if (p->pid == opts->pids[i]) {
                found = 1;
                break;
            }
        }
        if (!found) return 0;
    }

    if (opts->user_filter && p->uid != opts->user_filter_uid) {
        return 0;
    }

    if (opts->filter && p->command) {
        char *lower_cmd = strdup(p->command);
        for (char *c = lower_cmd; *c; c++) {
            *c = tolower((unsigned char)*c);
        }

        char *lower_filter = strdup(opts->filter);
        for (char *c = lower_filter; *c; c++) {
            *c = tolower((unsigned char)*c);
        }

        int passes = strstr(lower_cmd, lower_filter) != NULL;
        free(lower_cmd);
        free(lower_filter);

        if (!passes) return 0;
    }

    return 1;
}
EOF

