#!/usr/bin/env python3
"""
Process module for htop - reads process information from /proc
"""

import os
import pwd
import re
from pathlib import Path

def get_processes(args):
    """Get list of processes from /proc filesystem."""
    processes = []

    try:
        proc_dir = Path('/proc')
        for pid_dir in proc_dir.iterdir():
            if not pid_dir.name.isdigit():
                continue

            pid = int(pid_dir.name)

            try:
                process = read_process_info(pid)
                if process and passes_filters(process, args):
                    processes.append(process)
            except (FileNotFoundError, PermissionError, ValueError):
                continue
    except Exception:
        pass

    # Sort processes
    if args.get('sort_key'):
        # Implement sorting based on sort_key
        pass

    return processes

def read_process_info(pid):
    """Read process information from /proc/[pid]."""
    try:
        stat_path = f'/proc/{pid}/stat'
        comm_path = f'/proc/{pid}/comm'
        status_path = f'/proc/{pid}/status'

        # Read stat file
        with open(stat_path, 'r') as f:
            stat_line = f.read()

        # Parse stat file (simplified)
        parts = stat_line.split()
        if len(parts) < 20:
            return None

        # Read comm file
        try:
            with open(comm_path, 'r') as f:
                comm = f.read().strip()
        except:
            comm = '?'

        # Get UID from stat file directory
        stat = os.stat(f'/proc/{pid}')
        uid = stat.st_uid

        try:
            user = pwd.getpwuid(uid).pw_name
        except KeyError:
            user = str(uid)

        # Extract fields from stat
        try:
            ppid = int(parts[3])
            utime = int(parts[13])
            stime = int(parts[14])
            virt = int(parts[20])  # vsize
            res = int(parts[21])   # rss
        except (IndexError, ValueError):
            ppid = 0
            utime = 0
            stime = 0
            virt = 0
            res = res * 4096 if 'res' in locals() else 0  # Convert pages to bytes

        process = {
            'pid': pid,
            'ppid': ppid,
            'user': user,
            'uid': uid,
            'comm': comm,
            'virt': virt,
            'res': res,
            'cpu': 0.0,  # Simplified, would need more complex calculation
            'mem': 0.0,
        }

        return process

    except Exception as e:
        return None

def passes_filters(process, args):
    """Check if a process passes the current filters."""
    # Filter by PIDs
    if args.get('pids'):
        if process['pid'] not in args['pids']:
            return False

    # Filter by user
    if args.get('user_filter'):
        try:
            target_uid = pwd.getpwnam(args['user_filter']).pw_uid
        except KeyError:
            try:
                target_uid = int(args['user_filter'])
            except ValueError:
                return False

        if process['uid'] != target_uid:
            return False

    # Filter by command name
    if args.get('filter'):
        if args['filter'].lower() not in process['comm'].lower():
            return False

    return True
