#!/usr/bin/env python3
"""
UI module for htop - handles terminal display and interaction
"""

import curses
import os
import pwd
import time
import sys
from htop_process import get_processes

def run_interactive_ui(args):
    """Run the interactive UI using curses."""
    try:
        stdscr = curses.initscr()
    except curses.error as e:
        print(f"Error opening terminal: {e}", file=sys.stderr)
        return 1
    except Exception as e:
        print(f"Error opening terminal: unknown.", file=sys.stderr)
        return 1

    try:
        curses.cbreak()
        curses.noecho()
        stdscr.nodelay(True)
        curses.curs_set(0)

        # Set up colors if not in monochrome mode
        if not args['no_color']:
            try:
                curses.start_color()
                curses.use_default_colors()
                curses.init_pair(1, curses.COLOR_WHITE, curses.COLOR_BLUE)
                curses.init_pair(2, curses.COLOR_GREEN, -1)
                curses.init_pair(3, curses.COLOR_RED, -1)
            except:
                pass

        # Main loop
        running = True
        iteration = 0

        while running:
            try:
                stdscr.clear()
            except:
                pass

            # Get current processes
            processes = get_processes(args)

            # Draw the UI
            draw_ui(stdscr, processes, args)

            try:
                stdscr.refresh()
            except:
                pass

            # Handle input with timeout
            try:
                ch = stdscr.getch()
                if ch == ord('q'):
                    running = False
                elif ch == curses.KEY_UP:
                    pass  # Handle scrolling
                elif ch == curses.KEY_DOWN:
                    pass  # Handle scrolling
            except:
                pass

            # Sleep for the specified delay (in tenths of seconds)
            time.sleep(args['delay'] * 0.1)

            iteration += 1
            if args['max_iterations'] > 0 and iteration >= args['max_iterations']:
                running = False

        # Clean up
        curses.endwin()
        return 0

    except KeyboardInterrupt:
        try:
            curses.endwin()
        except:
            pass
        return 0
    except Exception as e:
        try:
            curses.endwin()
        except:
            pass
        print(f"Error: {e}", file=sys.stderr)
        return 1

def draw_ui(stdscr, processes, args):
    """Draw the main UI."""
    try:
        max_y, max_x = stdscr.getmaxyx()
    except:
        return

    # Draw header
    header = f"{'PID':>10} {'USER':>10} {'PPID':>10} {'COMM':>20} {'VIRT':>10} {'RES':>10} {'CPU%':>8}"
    try:
        stdscr.attron(curses.A_BOLD | curses.A_REVERSE)
        stdscr.addstr(0, 0, header[:max_x])
        stdscr.attroff(curses.A_BOLD | curses.A_REVERSE)
    except:
        pass

    # Draw processes
    for i, process in enumerate(processes):
        if i + 1 >= max_y - 1:  # Leave room for function bar
            break

        line = f"{process['pid']:>10} {process['user']:>10} {process['ppid']:>10} {process['comm'][:20]:>20} {process['virt']:>10} {process['res']:>10} {process['cpu']:>8.1f}"
        try:
            stdscr.addstr(i + 1, 0, line[:max_x])
        except curses.error:
            pass

    # Draw function bar
    if not args['no_function_bar']:
        footer = "F1Help  F2Setup  F3Search F4Filter F5Tree  F6SortBy F7Nice  F8Kill  F9Quit"
        try:
            stdscr.attron(curses.A_REVERSE)
            stdscr.addstr(max_y - 1, 0, footer[:max_x])
            stdscr.attroff(curses.A_REVERSE)
        except curses.error:
            pass
